async function main(): Promise<unknown> {
  const [command, ...args] = Bun.argv.slice(2);
  if (!command) fail("Missing command");
  const db = await load();

  if (command === "add") {
    const options = parseOptions(args, ["--title", "--tags", "--due"]);
    const title = options["--title"]?.trim();
    if (!title) fail("Title must not be empty");
    const due = options["--due"];
    if (due !== undefined && !isDate(due)) fail("Due date must be a valid YYYY-MM-DD date");
    const task: Task = { id: db.nextId++, title, status: "open", createdAt: new Date().toISOString(), tags: normalizedTags(options["--tags"]), ...(due ? { due } : {}) };
    db.tasks.push(task);
    await save(db);
    return task;
  }

  if (command === "list") {
    const options = parseOptions(args, ["--status", "--tag", "--overdue"]);
    if (options["--status"] !== undefined && options["--status"] !== "open" && options["--status"] !== "done") fail("Status must be open or done");
    if (options["--overdue"] !== undefined && !isDate(options["--overdue"])) fail("Overdue date must be a valid YYYY-MM-DD date");
    const tag = options["--tag"]?.trim().toLowerCase();
    if (options["--tag"] !== undefined && !tag) fail("Tag must not be empty");
    return db.tasks.filter((task) =>
      (options["--status"] === undefined || task.status === options["--status"]) &&
      (tag === undefined || task.tags.includes(tag)) &&
      (options["--overdue"] === undefined || (task.status === "open" && task.due !== undefined && task.due < options["--overdue"])),
    ).sort((a, b) => a.id - b.id);
  }

  if (command === "done" || command === "delete") {
    if (args.length !== 1) fail(`${command} requires exactly one ID`);
    const id = parseId(args[0]);
    const index = db.tasks.findIndex((task) => task.id === id);
    if (index === -1) fail(`Task not found: ${id}`);
    if (command === "delete") {
      const [deleted] = db.tasks.splice(index, 1);
      await save(db);
      return deleted;
    }
    const task = db.tasks[index];
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await save(db);
    }
    return task;
  }

  if (command === "stats") {
    if (args.length) fail("stats takes no arguments");
    const today = todayLocal();
    const open = db.tasks.filter((task) => task.status === "open");
    return { total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter((task) => task.due !== undefined && task.due < today).length };
  }
  fail(`Unknown command: ${command}`);
}

main().then((result) => console.log(JSON.stringify(result))).catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});
# Taskboard CLI

A dependency-free task manager for Bun. Data is stored in `.taskboard.json` in the current directory, or in the path set by `TASKBOARD_FILE`.

```sh
bun run src/cli.ts add --title "Write release notes" --tags docs,release --due 2026-10-01
bun run src/cli.ts list --status open --tag docs
bun run src/cli.ts list --overdue 2026-10-01
bun run src/cli.ts done 1
bun run src/cli.ts stats
bun run src/cli.ts delete 1
```

Each command emits exactly one JSON value to stdout. Invalid commands, flags, dates, IDs, and malformed database files produce a diagnostic on stderr and a non-zero exit code. Database writes use a sibling temporary file followed by an atomic rename.

## Self-test

```sh
bun test
```
import { expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = process.cwd();
let dir: string;
let database: string;

function setup() {
  dir = mkdtempSync(join(tmpdir(), "taskboard-test-"));
  database = join(dir, "tasks.json");
}

async function run(...args: string[]) {
  const proc = Bun.spawn(["bun", "run", join(root, "src/cli.ts"), ...args], { env: { ...process.env, TASKBOARD_FILE: database }, stdout: "pipe", stderr: "pipe" });
  return { exitCode: await proc.exited, out: await new Response(proc.stdout).text(), err: await new Response(proc.stderr).text() };
}

test("task lifecycle, filters, and persistence", async () => {
  setup();
  try {
    let result = await run("add", "--title", "  First task  ", "--tags", "Work,work, Urgent", "--due", "2020-01-01");
    expect(result.exitCode).toBe(0);
    expect(JSON.parse(result.out)).toMatchObject({ id: 1, title: "First task", status: "open", tags: ["work", "urgent"], due: "2020-01-01" });
    result = await run("add", "--title", "Second");
    expect(JSON.parse(result.out).id).toBe(2);
    result = await run("list", "--tag", "WORK", "--overdue", "2021-01-01");
    expect(JSON.parse(result.out)).toHaveLength(1);
    result = await run("done", "1");
    const completed = JSON.parse(result.out);
    expect(completed.status).toBe("done");
    result = await run("done", "1");
    expect(JSON.parse(result.out).completedAt).toBe(completed.completedAt);
    expect(JSON.parse(readFileSync(database, "utf8")).tasks).toHaveLength(2);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("invalid input and malformed data do not overwrite the database", async () => {
  setup();
  try {
    writeFileSync(database, "{not json");
    const result = await run("add", "--title", "Nope");
    expect(result.exitCode).not.toBe(0);
    expect(result.out).toBe("");
    expect(readFileSync(database, "utf8")).toBe("{not json");
  } finally { rmSync(dir, { recursive: true, force: true }); }
});
